// Place your own variable overrides here, these will override any Bootstrap and theme variables.

// brand colors (beecore-3)
$primary: #1D64ED !default;
$secondary: #0DD2F5 !default;
$info: #B72AF4 !default;
$teal: #00EBD7 !default;

// brand dark mode (beecore-3)
$body-bg-dark: #141515 !default;
$card-bg-dark: #262828 !default;
$body-color-dark: #FBF6F3 !default;

// brand light mode (beecore-3) — roles swapped from dark mode using the same brand hexes
$body-bg: #FBF6F3 !default;
$card-bg: #fff !default;
$body-color: #141515 !default;
